{%- set lines = [] -%}
{%- set by_code = {} -%}
{%- for d in doc.items if d.line_status != "Cancelled" and (d.qty or 0) - (d.short_qty or 0) > 0 -%}
{%- set q = (d.qty or 0) - (d.short_qty or 0) -%}
{%- if d.item_code in by_code -%}
{%- set r = by_code[d.item_code] -%}
{%- set _ = r.update({"qty": r.qty + q, "amount": r.amount + (d.amount or 0)}) -%}
{%- else -%}
{%- set r = {"item_code": d.item_code, "qty": q, "rate": d.rate, "amount": d.amount or 0,
    "supplier_part_no": d.supplier_part_no, "retail_sku_suffix": d.retail_sku_suffix,
    "description": frappe.db.get_value("Item", d.item_code, "description") or d.item_name} -%}
{%- set _ = by_code.update({d.item_code: r}) -%}
{%- set _ = lines.append(r) -%}
{%- endif -%}
{%- endfor -%}
